"""Scratch scouting helper (not shipped). Persistent profile per site, run steps, dump the page.
usage: pw.py SITE step1 step2 ...   steps: goto:URL  click:TEXT  css:SELECTOR  fill:SELECTOR=VALUE  press:KEY  wait:MS  frame
"""
import asyncio, json, os, sys
from pathlib import Path
from playwright.async_api import async_playwright

HERE = Path(__file__).parent
ACCESS = {a["siteId"]: a for a in json.loads(os.environ["CHALLENGE_SITE_ACCESS"])}


async def dump(page, out):
    out.append(f"URL: {page.url}  TITLE: {await page.title()}")
    for i, fr in enumerate(page.frames):
        try:
            txt = await fr.evaluate("() => document.body ? document.body.innerText : ''")
        except Exception as e:
            txt = f"<err {e}>"
        out.append(f"--- frame {i} {fr.url}\n{txt[:6000]}")
        try:
            ctrls = await fr.evaluate("""() => [...document.querySelectorAll('a,button,input,select,textarea,[role=button],[onclick]')].slice(0,150).map(e => {
                const t=(e.innerText||e.value||'').trim().slice(0,50); return `${e.tagName.toLowerCase()}${e.id?'#'+e.id:''}${e.name?'[name='+e.name+']':''}${e.type?'[type='+e.type+']':''} ${e.getAttribute('href')||''} "${t}"`})""")
            out.append("CONTROLS:\n" + "\n".join(ctrls))
        except Exception as e:
            out.append(f"<ctrl err {e}>")


async def main():
    site, steps = sys.argv[1], sys.argv[2:]
    a = ACCESS[site]
    async with async_playwright() as p:
        ctx = await p.chromium.launch_persistent_context(str(HERE / f"prof_{site}"), headless=True, viewport={"width": 1280, "height": 800})
        page = ctx.pages[0] if ctx.pages else await ctx.new_page()
        if page.url == "about:blank":
            await page.goto(a["url"])
        for s in steps:
            k, _, v = s.partition(":")
            if k == "goto": await page.goto(v if v.startswith("http") else a["url"].rstrip("/") + v)
            elif k == "click": await page.get_by_text(v, exact=False).first.click()
            elif k == "css": await page.locator(v).first.click()
            elif k == "fill":
                sel, _, val = v.partition("=")
                val = val.replace("$USER", a["credentials"]["username"]).replace("$PASS", a["credentials"]["password"])
                await page.locator(sel).first.fill(val)
            elif k == "press": await page.keyboard.press(v)
            elif k == "wait": await page.wait_for_timeout(int(v))
            elif k == "shot": await page.screenshot(path=str(HERE / v))
            await page.wait_for_timeout(600)
        out = []
        await dump(page, out)
        print("\n".join(out))
        await ctx.close()

asyncio.run(main())

